import {SnakeGame,SnakeWallet,SNAKE_SKINS} from './snake-model.js';
export function mountSnake(root,api){
 root.innerHTML=`<header class="snake-header"><button id="snake-back" type="button" aria-label="게임 선택">←</button><div><small>WORM GARDEN</small><h1>지렁이 정원</h1></div><div class="snake-wallet">🪙 <b id="snake-coins">0</b></div><button id="snake-shop" type="button">🎨 스킨</button></header><div class="snake-stats"><span>점수 <b id="snake-score">0</b></span><span>최고 <b id="snake-best">0</b></span><span>AI 지렁이 4마리</span></div><div class="snake-arena"><canvas id="snake-canvas" width="840" height="720" aria-label="지렁이 게임판. 방향 버튼 또는 화살표 키로 이동하세요."></canvas><div class="snake-overlay" id="snake-overlay"><div><h2 id="snake-title">지렁이 정원</h2><p id="snake-message">먹이를 모으며 AI 지렁이를 피해 보세요!</p><button id="snake-start" type="button">게임 시작</button></div></div></div><p class="snake-tip">방향 버튼이나 화면을 밀어서 움직여요 · 먹이 하나마다 🪙 10</p><div class="snake-controls"><button data-snake="up" aria-label="위">▲</button><div><button data-snake="left" aria-label="왼쪽">◀</button><button data-snake="down" aria-label="아래">▼</button><button data-snake="right" aria-label="오른쪽">▶</button></div></div><section id="snake-skins" hidden><div><h2>지렁이 스킨</h2><button id="snake-close" type="button">닫기 ×</button></div><p>지렁이 게임에서 모은 동전으로 구매해요.</p><div id="snake-skin-list"></div></section>`;
 const $=id=>root.querySelector('#'+id),canvas=$('snake-canvas'),ctx=canvas.getContext('2d');let wallet=null,game=null,last=0,lag=0,settled=false,touch=null;
 const active=()=>api.current()==='snake';const safe=fn=>{try{return fn();}catch(e){api.toast(e.message||'저장하지 못했어요.');return false;}};
 function refresh(){if(!wallet)return;$('snake-coins').textContent=wallet.data.coins.toLocaleString();$('snake-best').textContent=wallet.data.best.toLocaleString();$('snake-score').textContent=(game?.score||0).toLocaleString();}
 function finish(){if(!game||settled)return true;const ok=safe(()=>{wallet.settle(game.id,game.score,game.foodEaten);settled=true;refresh();return true;});if(!ok){$('snake-title').textContent='저장을 확인해 주세요';$('snake-message').textContent='기록을 저장한 뒤 다시 시작할 수 있어요.';$('snake-start').textContent='저장 다시 시도';$('snake-overlay').hidden=false;return false;}$('snake-title').textContent='이번 판 끝!';$('snake-message').textContent=`${game.score.toLocaleString()}점 · 지렁이 동전 ${game.score.toLocaleString()}개 획득`; $('snake-start').textContent='다시 시작';$('snake-overlay').hidden=false;api.active(false);return true;}
 function start(){if(game&&!settled&&!finish())return;game=new SnakeGame();settled=false;lag=0;last=0;$('snake-overlay').hidden=true;$('snake-skins').hidden=true;api.active(true);refresh();draw();}
 function draw(){const w=canvas.width,h=canvas.height,cols=game?.width||28,rows=game?.height||24,cell=w/cols;ctx.fillStyle='#112c31';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff0c';ctx.lineWidth=1;for(let x=0;x<=cols;x++){ctx.beginPath();ctx.moveTo(x*cell,0);ctx.lineTo(x*cell,h);ctx.stroke();}for(let y=0;y<=rows;y++){ctx.beginPath();ctx.moveTo(0,y*cell);ctx.lineTo(w,y*cell);ctx.stroke();}if(!game)return;for(const f of game.food){ctx.fillStyle='#ffda76';ctx.beginPath();ctx.arc((f.x+.5)*cell,(f.y+.5)*cell,cell*.17,0,Math.PI*2);ctx.fill();}const skin=SNAKE_SKINS.find(s=>s.id===wallet.data.skin);for(const s of game.all()){s.body.slice().reverse().forEach((p,i)=>{ctx.fillStyle=s.player?skin.color:s.color;ctx.beginPath();ctx.arc((p.x+.5)*cell,(p.y+.5)*cell,cell*(i===s.body.length-1?.46:.4),0,Math.PI*2);ctx.fill();});const head=s.body[0];if(head){ctx.fillStyle='#193333';ctx.beginPath();ctx.arc((head.x+.38)*cell,(head.y+.38)*cell,2.6,0,Math.PI*2);ctx.arc((head.x+.62)*cell,(head.y+.38)*cell,2.6,0,Math.PI*2);ctx.fill();}}}
 function renderShop(){$('snake-skin-list').replaceChildren();for(const s of SNAKE_SKINS){const button=document.createElement('button');button.type='button';const owned=wallet.data.owned.includes(s.id);button.innerHTML=`<i style="background:${s.color}"></i><strong>${s.name}</strong><small>${wallet.data.skin===s.id?'사용 중':owned?'선택하기':'🪙 '+s.price}</small>`;button.disabled=wallet.data.skin===s.id;button.onclick=()=>safe(()=>{wallet.buy(s.id);renderShop();refresh();draw();});$('snake-skin-list').append(button);}}
 $('snake-shop').onclick=()=>{if(!wallet)return;$('snake-skins').hidden=false;renderShop();};$('snake-close').onclick=()=>{$('snake-skins').hidden=true;};$('snake-back').onclick=()=>api.open('game-picker-dialog');$('snake-start').onclick=start;
 const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};root.querySelectorAll('[data-snake]').forEach(b=>b.onclick=()=>game?.turn(...dirs[b.dataset.snake]));globalThis.addEventListener('keydown',e=>{if(!active()||document.querySelector('dialog[open]'))return;const k={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'}[e.key];if(k){e.preventDefault();game?.turn(...dirs[k]);}});canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<12)return;game?.turn(...dirs[Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up']);});
 function frame(now){const dt=last?Math.min(.2,(now-last)/1000):0;last=now;if(active()&&game?.phase==='playing'&&!document.hidden&&!document.querySelector('dialog[open]')&&$('snake-skins').hidden){lag+=dt;while(lag>=.13&&game.phase==='playing'){game.step();lag-=.13;}refresh();draw();if(game.phase==='over')finish();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
 return {select(){wallet=new SnakeWallet();game=null;settled=false;$('snake-title').textContent='지렁이 정원';$('snake-message').textContent='먹이를 모으며 AI 지렁이를 피해 보세요!';$('snake-start').textContent='게임 시작';$('snake-overlay').hidden=false;$('snake-skins').hidden=true;api.active(false);refresh();draw();},leave(){if(game&&!settled&&!finish())return false;api.active(false);return true;},save(){},restart:start,openLocker(){if(wallet){$('snake-skins').hidden=false;renderShop();}},openRecords(){api.toast(`최고 기록 ${wallet?.data.best||0}점`);},focusMode(){api.toast('먹이를 모으며 AI 지렁이와 겨뤄요!');},mode:()=> 'classic'};
}
